INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('1','1','hero','0','Digital Healthcare Access Foundation: Strengthening Health Systems. Saving Lives.','<p>Advancing equitable and people-centred health systems through effective digital technologies.</p>','{"ctas": [{"href": "#programmes", "label": "Explore Our Work"}, {"href": "get-involved.html", "label": "Get Involved"}], "accent": ["Access Foundation", "Saving Lives."], "eyebrow": "Digital Healthcare Access Foundation"}',NULL,'2026-09-26 01:03:33');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('2','1','programmes','1','Our programme portfolio','<p>Each programme reflects our approach in practice: co-designed with healthcare professionals, grounded in evidence, and built for sustainable scale.</p>','{"eyebrow": "Our programmes", "featured": {"badge": "Flagship Programme", "title": "NICU Network Nigeria", "checks": ["Faster, safer NICU referrals", "Real-time bed availability", "Stronger communication between facilities", "Better outcomes for newborns"], "badge_plain": "Pilot launching 2026", "description": "A digital referral and coordination platform connecting hospitals and saving newborn lives."}}',NULL,'2026-08-06 01:49:26');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('3','1','about','2','The challenge we''re built to address','<p>Health systems across sub-Saharan Africa operate under considerable pressure: shortages of trained healthcare professionals, insufficient financing, fragmented service delivery, and unequal access to quality care.</p><p>Digital health technologies can strengthen communication, support clinical decision-making, improve care pathways, and generate timely information for planning. But the presence of technology does not automatically improve health outcomes. Solutions are too often fragmented, narrowly focused, or poorly integrated with existing systems.</p>','{"eyebrow": "Why this work is needed", "pullquote": "DHAF exists to change that. We build digital technologies designed as part of the broader health system, not apart from it."}',NULL,'2026-09-14 02:45:06');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('4','1','where_we_work','3','Working across sub-Saharan Africa',NULL,NULL,NULL,'2026-08-06 01:49:26');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('5','1','newsletter','4','Stay updated',NULL,NULL,NULL,'2026-08-06 01:49:26');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('6','1','final_cta','5','Partner With Us to Strengthen Health Systems','<p>DHAF works collaboratively with healthcare professionals, communities, institutions, and funders to develop digital solutions that are clinically relevant, contextually appropriate, and built to last. Join us.</p>',NULL,NULL,'2026-09-14 02:45:06');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('7','2','hero','0','Digital Healthcare Access Foundation','<p>Digital Healthcare Access Foundation (DHAF) is a non-profit organisation committed to strengthening health systems through effective, equitable, and sustainable digital technologies.</p><p>DHAF focuses on the shared digital infrastructure that allows health facilities to function as connected systems rather than isolated units. Our work is designed to improve visibility, communication, accountability, and coordination across facilities.</p><p>We work collaboratively with healthcare professionals, communities, health facilities, researchers, public institutions, and other partners to develop solutions that are clinically relevant, culturally appropriate, evidence-informed, and responsive to local contexts.</p><p>DHAF is based in Nigeria and is designed to contribute to health systems strengthening across Africa and other low- and middle-income settings.</p>','{"values": ["Clinically relevant", "Culturally appropriate", "Evidence-informed", "Responsive to local context"], "eyebrow": "Who We Are"}',NULL,'2026-09-14 02:45:06');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('8','2','vision','1','Vision','<p>Equitable, connected, and people-centred health systems in which effective digital technologies improve access to timely, high-quality healthcare for everyone.</p>',NULL,NULL,'2026-08-06 01:49:26');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('9','2','mission','2','Mission','<p>To strengthen health systems through digital technologies that improve coordination, communication, access, data use, and the delivery of equitable, high-quality healthcare.</p>',NULL,NULL,'2026-08-06 01:49:26');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('10','2','goals','3','DHAF aims to achieve the following goals',NULL,'{"goals": ["Develop effective and contextually appropriate digital health solutions that address priority health system challenges.", "Improve coordination and communication across healthcare facilities, professionals, communities, and public institutions.", "Strengthen the use of timely, accurate, and actionable data for clinical decision making, service planning, and quality improvement.", "Promote interoperability so digital technologies connect meaningfully with existing and future health information systems.", "Reduce avoidable delays and barriers to care, particularly among populations experiencing structural, geographic, social, or economic disadvantage.", "Advance health equity by ensuring digital transformation does not widen existing inequities or create new forms of exclusion.", "Strengthen the capacity of institutions to adopt, implement, evaluate, maintain, and govern digital health technologies.", "Generate evidence on the effectiveness, feasibility, acceptability, accessibility, sustainability, and scalability of digital health interventions."], "eyebrow": "Our goals"}',NULL,'2026-09-14 02:45:06');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('11','2','areas','4','Our areas of work','<p>Each area reflects how we work in practice.</p>','{"areas": [{"icon": "bulb", "text": "Developing and adapting digital technologies that respond to clearly defined health system needs.", "title": "Digital health innovation"}, {"icon": "network", "text": "Improving communication, care pathways, and continuity of care across facilities.", "title": "Healthcare coordination"}, {"icon": "chart", "text": "Strengthening the collection, exchange, and responsible use of health information.", "title": "Health information systems"}, {"icon": "blocks", "text": "Supporting institutions to adopt, use, and govern digital technologies.", "title": "Implementation & capacity strengthening"}, {"icon": "scope", "text": "Generating evidence on what works in real-world health system settings.", "title": "Monitoring, evaluation, research & learning"}, {"icon": "compass", "text": "Context-sensitive guidance for partners designing or scaling digital health technologies.", "title": "Advisory support"}], "eyebrow": "What we do"}',NULL,'2026-08-06 01:49:26');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('12','3','hero','0','The People Behind DHAF','<p>A multidisciplinary team bringing together expertise across healthcare, digital technology, public health, law, research, and coordination.</p>','{"eyebrow": "Our Team"}',NULL,'2026-09-14 02:45:06');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('13','3','intro','1',NULL,'<p>DHAF brings together professionals with expertise in healthcare, digital technology, public health, law, programme implementation, research, evaluation, grants, and coordination. Our multidisciplinary structure reflects the expertise required to develop effective digital health interventions: clinical insight, public health knowledge, technical expertise, community engagement, implementation support, ethical governance, and an understanding of the systems in which healthcare is delivered.</p>',NULL,NULL,'2026-09-14 02:45:06');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('14','4','hero','0','NICU Network Nigeria',NULL,'{"sub": "Strengthening Neonatal Care Through Better Coordination", "tag": "Connecting Hospitals. Saving Lives.", "endorsement": "A programme of Digital Healthcare Access Foundation"}',NULL,'2026-09-14 02:45:06');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('15','4','stats','1','Nigeria continues to face a substantial burden of neonatal mortality.','<p>Digital coordination built into the health system can change that.</p>','{"stats": [{"icon": "person", "label": "neonatal deaths per 1,000 live births in Nigeria", "value": "41", "suffix": "per 1,000", "context": "Nearly 2.4× the global average, one of the highest rates in the world"}, {"icon": "target", "label": "neonatal deaths in Nigeria every year", "value": "240,000+", "suffix": "", "context": "A preventable crisis that better-coordinated care can significantly reduce"}, {"icon": "case", "label": "across Nigeria to reach with coordinated NICU care", "value": "36", "suffix": "states", "context": "Beginning with the FCT Abuja pilot in 2026, designed to scale nationally"}, {"icon": "tool", "label": "pilot launch year for NICU Network Nigeria", "value": "2026", "suffix": "", "context": "Digital care coordination infrastructure, built with and for clinicians"}], "eyebrow": "Why this work matters"}',NULL,'2026-08-06 01:49:26');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('16','4','crisis','2','Nigeria''s neonatal crisis demands better coordination','<p>Nigeria continues to face a substantial burden of neonatal mortality. The 2024 Nigeria Demographic and Health Survey estimates that 41 newborns die during the first month of life for every 1,000 live births, considerably higher than the global rate of 17.2 per 1,000.</p><p>For newborns who require specialist care, timely transfer to the right facility can be critical. Yet care pathways are often fragmented across facilities, with limited visibility into where neonatal intensive care capacity is available.</p><p>The challenge is not only the availability of care. It is the ability to identify and reach it quickly, especially for families navigating an emergency.</p>','{"eyebrow": "Why this programme exists", "stat_panel": {"big": "41", "per": "per 1,000 live births", "what": "Neonatal deaths in Nigeria", "global": "17.2", "source": "NDHS 2024", "global_label": "Global rate"}}',NULL,'2026-08-06 01:49:26');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('17','4','lifecycle','3','What NICU Network does','<p>NICU Network is a digital health solution that supports neonatal care services by helping healthcare teams work more effectively across participating facilities.</p><p>The platform is designed to strengthen coordination, improve access to timely information, and support decision-making within neonatal care pathways. By facilitating collaboration between healthcare providers and institutions, it aims to contribute to more responsive and connected care for newborns requiring specialised services.</p><p>NICU Network is developed to fit within existing healthcare environments and workflows, ensuring that it remains practical, relevant, and sustainable in routine clinical practice.</p>','{"stages": [{"pill": "REFER", "color": "amber", "title": "Acceptance", "detail": "Nurse holds bed"}, {"pill": "CONFIRMED", "color": "teal", "title": "Confirmation", "detail": "After clinical handoff"}, {"pill": "ADMITTED", "color": "purple", "title": "Admission", "detail": "On patient arrival"}], "eyebrow": "A better way to coordinate neonatal care"}',NULL,'2026-08-06 01:49:26');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('18','4','pilot','4','The pilot','<p>NICU Network is launching as a pilot in the Federal Capital Territory of Abuja in 2026, working with a group of anchor hospitals that provide neonatal intensive care.</p><p>The pilot is being developed in close partnership with the clinical teams who will use it, and will lay the groundwork for wider expansion.</p>','{"callout": "Pilot launching 2026 in the Federal Capital Territory, Abuja", "eyebrow": "Where we are starting"}',NULL,'2026-08-06 01:49:26');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('19','4','join','5','Join the network',NULL,'{"cards": [{"items": ["Access to a shared, real-time view of neonatal care capacity across the network", "A more structured and dependable process for transferring newborns to the right facility", "A collaborative community of clinical teams working toward better newborn survival"], "title": "What partners gain"}, {"items": ["A shared commitment to participating actively in the network", "Supporting your clinical teams to use the platform", "Working with us through onboarding"], "title": "What partnership involves"}, {"text": "We are currently working with hospitals in the Federal Capital Territory of Abuja and welcome interest from facilities that provide or refer for neonatal care.", "title": "Who can join"}], "quote": "Every hospital that joins makes the network stronger. A stronger network means more newborns reach the right care in time.", "eyebrow": "Partner with NICU Network"}',NULL,'2026-08-06 01:49:26');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('20','5','hero','0','Latest from DHAF','<p>Updates from our programmes, our thinking on health systems, and news from the organisation.</p>','{"eyebrow": "News & Stories", "categories": ["All", "Programme Update", "Health Systems", "Organisation", "Research"]}',NULL,'2026-09-14 02:45:06');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('21','6','hero','0','Get in Touch','<p>Whether you have a question, want to partner, or are a journalist, we would be glad to hear from you.</p>',NULL,NULL,'2026-08-06 01:49:26');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('22','7','hero','0','Support Our Work','<p>DHAF is a non-profit organisation. Donations support the development, implementation, and evaluation of digital health solutions that strengthen health systems and improve access to quality care.</p>','{"eyebrow": "Donate"}',NULL,'2026-09-14 02:45:06');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('23','7','note','1',NULL,'<p>Donation links will be live at launch. Contact us to discuss supporting our work directly.</p>',NULL,NULL,'2026-08-08 01:54:47');
INSERT INTO page_sections (id,page_id,section_key,sort_order,heading,body_html,data_json,image_id,updated_at) VALUES ('24','7','final_cta','2','Every successful referral is a life reached in time.','<p>Your support keeps the network growing — hospital by hospital, referral by referral.</p>',NULL,NULL,'2026-08-06 01:49:26');
INSERT INTO team_tiers (id,tier_key,label,title,intro,is_published,sort_order,created_at,updated_at) VALUES ('1','trustees','Governance','Board of Trustees','Statutory oversight of Digital Healthcare Access Foundation. Five to seven members, convened quarterly by the Chair, responsible for fiduciary oversight, strategic direction, and appointment of the Executive Director.','0','0','2026-08-09 21:18:19','2026-09-14 03:17:50');
