INSERT INTO news_articles (id,title,slug,category,summary,lede,body_html,author,featured_image_id,icon_type,background_gradient,status,publish_date,created_at,updated_at) VALUES ('1','NICU Network Nigeria: Preparing for the 2026 FCT Pilot','article-fct-pilot','Programme Update','DHAF is finalising clinical partnerships and technical infrastructure ahead of the NICU Network Nigeria pilot launch in the Federal Capital Territory.','DHAF is finalising clinical partnerships and technical infrastructure ahead of the NICU Network Nigeria pilot launch in the Federal Capital Territory.','<p></p>','Digital Healthcare Access Foundation','9','pulse','navy','published','2026-08-10','2026-08-06 01:49:26','2026-09-14 03:17:50');
