INSERT INTO sdg_goals (id,sdg_number,target_label,alignment_type,title,description,icon,color_class,sort_order) VALUES ('1','3','Target 3.2','primary','End preventable newborn deaths','The 2030 target is an NMR of 12 per 1,000 live births. Nigeria stands at 41 (NDHS 2024). NICU Network removes the coordination failure behind these preventable deaths.','pulse','sdg-3','0');
INSERT INTO sdg_goals (id,sdg_number,target_label,alignment_type,title,description,icon,color_class,sort_order) VALUES ('2','3','Target 3.8','primary','Universal health coverage','Equitable access to neonatal intensive care becomes a structural feature of the referral system — not a function of which hospital a family happens to reach.','pulse','sdg-3','1');
INSERT INTO sdg_goals (id,sdg_number,target_label,alignment_type,title,description,icon,color_class,sort_order) VALUES ('3','3','Target 3.1','primary','Reduce maternal mortality','The high-risk deliveries that generate the most urgent NICU referrals are the same clinical events associated with the greatest maternal risk.','pulse','sdg-3','2');
INSERT INTO sdg_goals (id,sdg_number,target_label,alignment_type,title,description,icon,color_class,sort_order) VALUES ('4','10',NULL,'supporting','Reduced inequalities','Coordinating referrals across teaching, district, and general hospitals works directly against the geographic and institutional inequality that determines survival outcomes.','equality','sdg-10','3');
INSERT INTO sdg_goals (id,sdg_number,target_label,alignment_type,title,description,icon,color_class,sort_order) VALUES ('5','17',NULL,'supporting','Partnerships for the goals','A multi-hospital network spanning government, teaching, and district facilities embodies the cross-sector collaboration SDG 17 calls for.','partners','sdg-17','4');
